# Helpers
exceptions = []
def log(case_ref, table, column, value, issue, severity="ACTION"):
    exceptions.append({"severity": severity, "caseReference": case_ref, "table": table, "column": column,
                       "value": None if value is None else str(value)[:300], "issue": issue})

extra_notes = []   
def blank(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or str(v).strip() in ("", "nan", "NaT", "None")

CHAR_MAP = str.maketrans({
    "\u00a0": " ", "\u2007": " ", "\u202f": " ",                     # non-breaking spaces
    "\u2018": "'", "\u2019": "'", "\u201b": "'",                     # smart single quotes
    "\u201c": '"', "\u201d": '"',                                    # smart double quotes
    "\u2013": "-", "\u2014": "-",                                    # en/em dash
    "\u2022": "-", "\u00b7": "-",                                    # bullets
    "\u2026": "...",                                                 # ellipsis
    "\u200b": None, "\u200c": None, "\u200d": None, "\ufeff": None,  # zero-width / BOM
})
cleansed = {}   # before -> after, for _cleansing.csv

def clean(v):
    if blank(v):
        return None
    if isinstance(v, str):
        before = v
        v = v.replace("_x000D_", "\n").translate(CHAR_MAP)
        v = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", "", v)      # control chars
        if FLATTEN_NEWLINES:
            v = re.sub(r"\s*[\r\n]+\s*", " | ", v)
        v = re.sub(r"[ \t]{2,}", " ", v).strip()
        if v != before.strip() and before not in cleansed:
            cleansed[before] = v
        return v or None
    return v

DATE_IN_TEXT = re.compile(r"\b(\d{1,2}/\d{1,2}/\d{2,4})\b")

def to_date(v, ref=None, table=None, col=None):
    if blank(v):
        return None
    if isinstance(v, (datetime, pd.Timestamp)):
        return pd.Timestamp(v).strftime("%Y-%m-%d")
    text = str(v).strip()
    d = pd.to_datetime(text, dayfirst=True, errors="coerce")
    if not pd.isna(d):
        return d.strftime("%Y-%m-%d")
    m = DATE_IN_TEXT.search(text)
    if m:
        d = pd.to_datetime(m.group(1), dayfirst=True, errors="coerce")
        if not pd.isna(d):
            extra_notes.append({"caseReference": ref, "noteType": col, "noteText": f"{col}: {clean(text)}"})
            log(ref, table, col, v, "Date taken from text, full text kept in S62aCaseNote", "INFO")
            return d.strftime("%Y-%m-%d")
    if KEEP_DATELESS_TEXT_AS_NOTE:
        extra_notes.append({"caseReference": ref, "noteType": col, "noteText": f"{col}: {clean(text)}"})
        log(ref, table, col, v, "No date in value, set to null, text kept in S62aCaseNote", "INFO")
    else:
        log(ref, table, col, v, "No date in value, set to null, text removed", "INFO")
    return None

def split_multi(v):
    """'[a, b]' or '{a, b}' -> ['a','b'];  'a; b' -> ['a','b'];  scalar -> [scalar]."""
    if blank(v):
        return []
    s = str(v).strip()
    m = re.match(r"^[\[{](.*)[\]}]$", s, re.S)
    if m:
        return [x.strip() or None for x in m.group(1).split(",")]
    if ";" in s:
        return [x.strip() or None for x in s.split(";")]
    return [v]

def is_date_field(name):
    return bool(re.search(r"date$|Date$", str(name)))

def get(row, col):
    return row[col] if col in row.index else None

# 1a. One case per reference: the master has one row per repeating group, so a case can span several rows
GROUP_COLUMNS = {
    "ParkingGroupID", "ParkingVehicleType", "ParkingExistingSpaces", "ParkingProposedSpaces", "ParkingSpaceDifference",
    "NonResGroupID", "UseClass", "FloorspaceChange", "ExistingFloorspaceSqM", "FloorspaceLostSqM", "FloorspaceProposedSqM",
    "WasteType", "VoidCapacityCubicMetres", "LiquidWasteMaxAnnualThroughput", "WasteMaxThroughputType",
    *[f"{h}Housing{x}" for h in ("Existing", "Proposed")
      for x in ("GroupID", "OccupancyType", "UnitType", "1BedCount", "2BedCount", "3BedCount", "4PlusBedCount",
                "UnknownBedCount", "TotalUnits")],
}
rows_by_ref = {ref: g for ref, g in cases.groupby("Case reference", sort=False)}
merged = []
for ref, g in rows_by_ref.items():
    rec = g.iloc[0].copy()
    if len(g) > 1:
        for c in g.columns:
            if c in GROUP_COLUMNS:
                continue
            vals = [v for v in g[c] if not blank(v)]
            if vals:
                rec[c] = vals[0]
            if len({str(v).strip() for v in vals}) > 1:
                log(ref, "scope", c, " | ".join(dict.fromkeys(str(v)[:60] for v in vals)),
                    f"{len(g)} source rows for this case disagree, first value kept")
        log(ref, "scope", "Case reference", len(g), f"{len(g)} source rows merged into one case", "INFO")
    merged.append(rec)
cases = pd.DataFrame(merged).reset_index(drop=True)
print(f"Source rows in scope: {sum(len(g) for g in rows_by_ref.values())} -> cases: {len(cases)}")

# 1a2. Pre-application cases get /PRE on the end of the reference (agreed with Sophie: phase decides).
# Runs after numbering and merging, so it never changes which numbers are used.
# GUIDs are built from the reference WITHOUT /PRE (base_ref, used in 7b), so ids don't change
# and the documents notebook still matches.
def base_ref(ref):
    return re.sub(rf"{re.escape(PRE_SUFFIX)}$", "", str(ref))

def is_pre_app(row):
    phase = str(get(row, "Application phase") or "").strip().lower()
    return phase == "pre-application" or (phase in ("", "nan", "none") and row._ref_class == "PRE_APP")

renamed = {}
for i, row in cases.iterrows():
    ref = row["Case reference"]
    if is_pre_app(row) and not ref.endswith(PRE_SUFFIX):
        renamed[ref] = ref + PRE_SUFFIX
        cases.at[i, "Case reference"] = renamed[ref]

# keep everything already keyed on the old reference in step
rows_by_ref = {renamed.get(k, k): g for k, g in rows_by_ref.items()}
for n in extra_notes:
    n["caseReference"] = renamed.get(n["caseReference"], n["caseReference"])
for g in generated_refs:
    g["generatedReference"] = renamed.get(g["generatedReference"], g["generatedReference"])
for e in exceptions:
    e["caseReference"] = renamed.get(e["caseReference"], e["caseReference"])

print(f"Pre-application references suffixed with {PRE_SUFFIX}: {len(renamed)}")

# 1. Flat 1:1 tables driven by the mapping file (S62aCase, S62aDates, S62aFees)
FLAT_TABLES = ["S62aCase", "S62aDates", "S62aFees"]
SPECIAL = {
    "Case reference", "Pre-application status", "Application Status",
    "Pre-app/Application received date", "Pre-app received date",
}
flat_map = mapping[mapping.target_table.isin(FLAT_TABLES) & mapping.target_field.notna()]
note_cols = flat_map[flat_map.target_field == "Notes"].source_column.tolist()
flat_map = flat_map[(flat_map.target_field != "Notes") & ~flat_map.source_column.isin(SPECIAL)]

CUSTOM_COLUMNS = {  
    "ParkingGroupID", "ParkingSpaceDifference", "NonResGroupID", "WasteMaxThroughputType",
    "TotalProposedResidentialUnits", "NetResidentialUnitChange", "NetAdditionalFloorspaceSqM",
    "NonResExistingFloorspaceSqM", "NonResFloorspaceLostSqM", "NonResFloorspaceProposedSqM", "NonResNetFloorspaceSqM",
}
KNOWN_TABLES = set(FLAT_TABLES) | {"Lpa", "Contact", "Address", "S62aToApplicant", "S62aCaseInspector", "S62aEvent",
                                   "S62aVehicleParking", "S62aNonResidentialFloorspace",
                                   "S62aNonResidentialFloorspaceArea", "S62aResidentialHousing", "S62aCaseWasteType"}
for _, m in mapping.iterrows():
    c = m.source_column
    if c in CUSTOM_COLUMNS or c in SPECIAL or c not in cases.columns:
        continue
    if m.target_table in KNOWN_TABLES:
        continue
    has_data = cases[c].map(lambda v: not blank(v)).any()
    if has_data:
        log(None, "mapping", c, f"{m.target_table}.{m.target_field}", "Has data but no valid target in mapping, not migrated")
    else:
        log(None, "mapping", c, f"{m.target_table}.{m.target_field}", "No target in mapping, but column is empty so nothing lost", "INFO")

tables = {t: [] for t in FLAT_TABLES}
for _, row in cases.iterrows():
    ref = row["Case reference"]
    recs = {t: {"caseReference": ref} for t in FLAT_TABLES}

    for _, m in flat_map.iterrows():
        v = get(row, m.source_column)
        field = re.sub(r"\s+", "", m.target_field)
        recs[m.target_table][field] = to_date(v, ref, m.target_table, m.source_column) if is_date_field(field) else clean(v)

    # pre-app vs application: use Application phase, fall back to reference format
    phase = str(get(row, "Application phase") or "").strip().lower()
    is_pre = phase == "pre-application" or (phase in ("", "nan") and row._ref_class == "PRE_APP")

    # status: pre-app status for pre-app cases, else application status
    pre_s, app_s = clean(get(row, "Pre-application status")), clean(get(row, "Application Status"))
    recs["S62aCase"]["S62aStatus"] = (pre_s or app_s) if is_pre else app_s

    # combined received date -> pre-app or application field (dedicated pre-app column wins)
    # Received dates: legacy fills both columns (dedicated wins), live only fills the combined column.
    pre_rd  = to_date(get(row, "Pre-app received date"), ref, "S62aDates", "Pre-app received date")
    comb_rd = to_date(get(row, "Pre-app/Application received date"), ref, "S62aDates", "Pre-app/Application received date")

    if is_pre:
        if pre_rd and comb_rd and pre_rd != comb_rd:
            log(ref, "S62aDates", "preApplicationReceivedDate", f"{pre_rd} | {comb_rd}",
                "Both pre-app received date columns filled and differ, 'Pre-app received date' kept")
        recs["S62aDates"]["preApplicationReceivedDate"] = pre_rd or comb_rd
    else:
        recs["S62aDates"]["preApplicationReceivedDate"] = None
        if comb_rd and not recs["S62aDates"].get("applicationReceivedDate"):
            recs["S62aDates"]["applicationReceivedDate"] = comb_rd


    for t in FLAT_TABLES:
        tables[t].append(recs[t])

# 1b. Notes: one row per note column with a value
note_rows = []
for _, row in cases.iterrows():
    for c in note_cols:
        v = get(row, c)
        if not blank(v):
            text = clean(to_date(v) if isinstance(v, (datetime, pd.Timestamp)) else v)
            label = "" if c.strip().lower() == "notes" else f"{c}: "
            note_rows.append({"caseReference": row["Case reference"], "noteType": c, "noteText": f"{label}{text}"})

# 2. LPAs (primary + secondary) and their contacts
def col(row, name):
    """Find a column ignoring repeated spaces (the master has both 'Secondary LPA - x' and 'Secondary LPA  - x')."""
    key = re.sub(r"\s+", " ", name).strip().lower()
    for c in row.index:
        if re.sub(r"\s+", " ", str(c)).strip().lower() == key:
            return row[c]
    return None

LPA_SOURCES = [("Primary", "LPA", "LPA contact"), ("Secondary", "Secondary LPA", "Secondary LPA")]
lpa_reference = pd.read_excel(lpas_path, sheet_name="Sheet1", dtype=str)
missing_columns = {"id", "name"} - set(lpa_reference.columns)
if missing_columns:
    raise ValueError(f"LPAs.xlsx is missing required columns: {sorted(missing_columns)}")
lpa_reference = lpa_reference[["id", "name"]].copy()
for field in ("id", "name"):
    lpa_reference[field] = lpa_reference[field].map(clean)
lpa_reference = lpa_reference.dropna(subset=["id", "name"])
def lpa_name_key(value):
    normalized = str(value).casefold().strip()
    normalized = re.sub(r"\s+lpa\s*$", "", normalized)
    normalized = re.sub(r",?\s+city\s+of$", "", normalized)
    normalized = re.sub(r"\s+(?:district|borough|city|county|metropolitan|unitary)\s+council$", "", normalized)
    normalized = re.sub(r"\s+council$", "", normalized)
    normalized = re.sub(r"\s+(?:district|borough|city|county|metropolitan|unitary)$", "", normalized)
    return re.sub(r"[^a-z0-9]", "", normalized)
lpa_reference["name_key"] = lpa_reference["name"].map(lpa_name_key)
duplicate_names = lpa_reference.loc[lpa_reference["name_key"].duplicated(keep=False), "name"].tolist()
if duplicate_names:
    raise ValueError(f"LPAs.xlsx contains duplicate LPA names: {duplicate_names[:10]}")
invalid_ids = []
for lpa_id in lpa_reference["id"]:
    try:
        uuid.UUID(lpa_id)
    except (ValueError, TypeError, AttributeError):
        invalid_ids.append(lpa_id)
if invalid_ids:
    raise ValueError(f"LPAs.xlsx contains invalid GUIDs: {invalid_ids[:10]}")
lpa_ids_by_name = dict(zip(lpa_reference["name_key"], lpa_reference["id"]))
def resolve_lpa_id(name, case_ref, role):
    name_key = lpa_name_key(name)
    if not name_key:
        return None
    exact_id = lpa_ids_by_name.get(name_key)
    if exact_id is not None:
        return exact_id
    matches = lpa_reference[lpa_reference["name_key"].str.contains(name_key, regex=False)]
    if len(matches) == 1:
        return matches.iloc[0]["id"]
    if len(matches) > 1:
        candidates = matches["name"].tolist()
        raise ValueError(f"Ambiguous LPA name for {case_ref} ({role}): '{name}' matches {candidates}")
    return None
lpa_rows = []
unmatched_lpas = []
for _, row in cases.iterrows():
    ref = row["Case reference"]
    for role, lpa_col, contact_prefix in LPA_SOURCES:
        lpa = col(row, lpa_col)
        first, last = col(row, f"{contact_prefix} - First name"), col(row, f"{contact_prefix} - Last name")
        phone, email = col(row, f"{contact_prefix} - Phone number"), col(row, f"{contact_prefix} - Email")
        has_contact = any(not blank(x) for x in (first, last, phone, email))
        if blank(lpa):
            if has_contact:
                log(ref, "S62aCaseLpa", lpa_col, email or first, f"{role} LPA contact given but no {role.lower()} LPA name, not migrated")
            continue
        lpa_name = clean(lpa)
        lpa_id = resolve_lpa_id(lpa_name, ref, role)
        if lpa_id is None:
            unmatched_lpas.append(f"{ref} ({role}): {lpa_name}")
        name = " ".join(str(clean(x)) for x in (first, last) if not blank(x)) or None
        lpa_rows.append({"caseReference": ref, "lpaRole": role, "lpa": lpa_name, "lpaId": lpa_id,
                         "contactName": name, "telephoneNumber": clean(phone),
                         "email": clean(re.sub(r"^mailto:", "", str(email), flags=re.I)) if not blank(email) else None})
tables["S62aCaseLpa"] = lpa_rows
if unmatched_lpas:
    raise ValueError("No matching LPA GUID found in INPUT/MASTER/LPAs.xlsx for: " + "; ".join(unmatched_lpas[:20]))

# 3. Contacts + addresses (agent, applicant, site). Multiple people per cell split on ';'
contact_rows, address_rows = [], []
for _, row in cases.iterrows():
    ref = row["Case reference"]
    for role in ["Agent", "Applicant"]:
        parts = {k: split_multi(get(row, f"{role} {k}")) for k in ["first name", "last name", "email", "phone"]}
        org = get(row, f"{role} organisation name")
        n = max([len(v) for v in parts.values()] + [1 if not blank(org) else 0])
        lens = {k: len(v) for k, v in parts.items() if len(v) > 1}
        if len(set(lens.values())) > 1:
            log(ref, "Contact", role, lens, "Multi-person cells have different counts, aligned by position")
        for i in range(n):
            pick = lambda k: parts[k][i] if i < len(parts[k]) else None
            email = pick("email")
            contact_rows.append({
                "caseReference": ref, "contactRole": role, "sequence": i + 1,
                "orgName": clean(org) if i == 0 else None,
                "firstName": clean(pick("first name")), "lastName": clean(pick("last name")),
                "email": clean(re.sub(r"^mailto:", "", str(email), flags=re.I)) if not blank(email) else None,
                "telephoneNumber": clean(pick("phone")),
                "applicantType": clean(get(row, "Applicant type")) if role == "Applicant" and i == 0 else None,
            })
    for role, cols in {
        "Agent":     ["Agent address 1", "Agent address 2", "Agent town or city", "Agent county", "Agent postcode"],
        "Applicant": ["Applicant address 1", "Applicant address 2", "Applicant town or city", "Applicant county", "Applicant postcode"],
        "Site":      ["Site address 1", "Site address 2", "Site town or city", "Site county", "Site post code"],
    }.items():
        vals = [clean(get(row, c)) for c in cols]
        if any(v is not None for v in vals):
            address_rows.append(dict(zip(["caseReference", "addressType", "line1", "line2", "townCity", "county", "postcode"],
                                         [ref, role] + vals)))
tables["Contact"] = contact_rows
tables["Address"] = address_rows

# 5. Events (one row per event type that has data)
EVENTS = {
    "SiteVisit":         {"Site visit type": "siteVisitType", "Site visit date": "eventDate"},
    "ProcedureNotice":   {"Notice of procedure date": "eventDate"},
    "Hearing":           {"Hearing  date": "eventDate", "Hearing notification date": "notificationDate",
                          "Hearing issues report published date": "issuesReportPublishedDate",
                          "Hearing duration - prep (days)": "prepDuration",
                          "Hearing duration - sitting (days)": "sittingDuration",
                          "Hearing duration - reporting (days)": "reportingDuration", "Hearing venue": "venue"},
    "AdditionalMeeting": {"Additional meeting required date": "eventDate"},
}
event_rows = []
for _, row in cases.iterrows():
    for etype, cols in EVENTS.items():
        if all(blank(get(row, c)) for c in cols):
            continue
        rec = {"caseReference": row["Case reference"], "eventType": etype}
        for c, f in cols.items():
            v = get(row, c)
            rec[f] = to_date(v, row["Case reference"], "S62aEvent", c) if "Date" in f or f == "eventDate" else clean(v)
        event_rows.append(rec)
tables["S62aEvent"] = event_rows

# 6. Repeating groups: explode '[a, b]' / '{a, b}' cells into child rows
def derive_parking(lists, ambiguous, n):
    """existing + difference = proposed, so a missing one can be rebuilt when the other two line up."""
    def nums(f):
        v = lists.get(f, [])
        try:
            return [float(x) for x in v] if len(v) == n and f not in ambiguous else None
        except (TypeError, ValueError):
            return None
    rules = {"existingSpaces":  lambda p, e, d: [a - b for a, b in zip(p, d)] if p and d else None,
             "proposedSpaces":  lambda p, e, d: [a + b for a, b in zip(e, d)] if e and d else None,
             "spaceDifference": lambda p, e, d: [a - b for a, b in zip(p, e)] if p and e else None}
    resolved = {}
    for f, rule in rules.items():
        if f not in ambiguous:
            continue
        derived = rule(nums("proposedSpaces"), nums("existingSpaces"), nums("spaceDifference"))
        original = {float(x) for x in ambiguous[f] if not blank(x)}
        if derived and original <= set(derived):
            resolved[f] = [int(x) if x == int(x) else x for x in derived]

    # single leftover values: try each group position (0 elsewhere) and keep a placement where
    # existing + difference = proposed holds for every group; first-group placement preferred
    singles = [f for f in ("existingSpaces", "proposedSpaces", "spaceDifference")
               if f in ambiguous and f not in resolved and len(ambiguous[f]) == 1]
    if singles:
        from itertools import product
        def as_list(f, pos=None):
            if f in resolved:
                return [float(x) for x in resolved[f]]
            if f in singles:
                return [float(ambiguous[f][0]) if i == pos else 0.0 for i in range(n)]
            return nums(f)
        for combo in product(range(n), repeat=len(singles)):
            pos = dict(zip(singles, combo))
            e, p_, d = (as_list(f, pos.get(f)) for f in ("existingSpaces", "proposedSpaces", "spaceDifference"))
            try:
                if e and p_ and d and all(a + b == c for a, b, c in zip(e, d, p_)):
                    for f in singles:
                        resolved[f] = [int(x) if x == int(x) else x for x in as_list(f, pos[f])]
                    break
            except (TypeError, ValueError):
                break
    return resolved

COUNT_FIELDS = {"existingSpaces", "proposedSpaces", "spaceDifference", "bedroomsOne", "bedroomsTwo", "bedroomsThree",
                "bedroomsFourPlus", "bedroomsUnknown", "totalUnits", "netAdditionalGross", "existingGross",
                "grossLost", "grossProposed", "voidCapacity", "maxAnnualThroughput"}

def group_lists(ref, row, cols, id_col, table):
    """One row per case: split '[a, b]' cells. Several source rows: one entry per distinct group, scalar values only."""
    g = rows_by_ref[ref]
    if len(g) == 1:
        return {f: split_multi(get(row, c)) for c, f in cols.items()}
    present = [(c, f) for c, f in cols.items() if c in g.columns]
    seen = {}
    for _, r in g.iterrows():
        vals = {f: clean(r[c]) for c, f in present}
        if all(v is None for v in vals.values()):
            continue
        key = vals.get(id_col) if id_col and vals.get(id_col) is not None else tuple(vals.values())
        if key not in seen:
            seen[key] = vals
            continue
        for f, v in vals.items():
            if v is None:
                continue
            if seen[key][f] is None:
                seen[key][f] = v
            elif str(seen[key][f]) != str(v):
                log(ref, table, f, v, f"Group {key} has different values across source rows, kept {seen[key][f]}")
    groups = list(seen.values())
    have = {f for _, f in present}
    return {f: [x[f] for x in groups] if f in have and any(x[f] is not None for x in groups) else [] for f in cols.values()}

def explode_group(table, cols, extra=None, derive=None):
    """Horizon joins each attribute as a DISTINCT list with nulls dropped, so values can only be
    matched to groups when an attribute has one value per group. Anything else is ambiguous:
    left null and logged, to be fixed from row-level Horizon data."""
    rows = []
    id_col = "groupId" if "groupId" in cols.values() else None
    for _, row in cases.iterrows():
        ref = row["Case reference"]
        lists = group_lists(ref, row, cols, id_col, table)
        n = (len(lists[id_col]) if id_col else 0) or max(len(v) for v in lists.values())
        if n == 0:
            continue
        ambiguous = {f: v for f, v in lists.items() if f != id_col and 0 < len(v) != n}
        if derive and ambiguous:
            for f, vals in derive(lists, ambiguous, n).items():
                log(ref, table, f, ambiguous.pop(f), f"Rebuilt from the other parking columns: {vals}", "INFO")
                lists[f] = vals
        # single value for several groups: text -> same value on every group; number -> first group, 0 on the rest
        for f in [f for f, v in ambiguous.items() if len(v) == 1]:
            v = ambiguous.pop(f)[0]
            if f in COUNT_FIELDS:
                lists[f] = [v] + [0] * (n - 1)
                log(ref, table, f, v, f"Assumed: single value put on group 1, 0 on the other {n - 1} group(s)", "INFO")
            else:
                lists[f] = [v] * n
                log(ref, table, f, v, f"Assumed: single value applies to all {n} groups", "INFO")
        for f, v in ambiguous.items():
            filled = "set to 0" if NULL_COUNTS_TO_ZERO and f in COUNT_FIELDS else "left null"
            log(ref, table, f, get(row, next(c for c, ff in cols.items() if ff == f)),
                f"Ambiguous: {len(v)} values for {n} groups, {filled}; source values not migrated (check Horizon)")
        for i in range(n):
            rec = {"caseReference": ref, "sequence": i + 1, **(extra or {})}
            for f, vals in lists.items():
                rec[f] = clean(vals[i]) if f not in ambiguous and i < len(vals) else None
            if any(rec[f] is not None for f in lists if f != id_col) or ambiguous:
                if NULL_COUNTS_TO_ZERO:
                    for f in lists:
                        if f in COUNT_FIELDS and rec[f] is None:
                            rec[f] = 0
                rows.append(rec)
    return rows

